{
  "technical_and_design_decisions": [
    "Use versioned Hyperledger Fabric module dependencies and import reusable upstream packages instead of maintaining copied or modified implementations in the Go SDK.",
    "Preserve the existing Go SDK public APIs where practical by adding compatibility adapters only when upstream package APIs differ.",
    "Treat gossip protoext, cauthdsl, ccprovider, ledger, common/core utilities, configtxgen, and configtxlator as separately migrated dependency areas so each can be validated independently.",
    "Implement the chaincode go.mod behavior as a narrowly scoped, temporary compatibility path, with explicit documentation and tests to prevent it from becoming a general dependency-resolution feature.",
    "Prefer source-compatible changes over local forks; generated protobuf code and protocol formats will not be changed unless required by dependency alignment.",
    "Use unit, package-level integration, and existing SDK regression tests as the primary validation strategy, with focused tests for dependency resolution and migrated functionality.",
    "Update module metadata, import paths, build scripts, and CI together so the increment is reproducible from a clean checkout."
  ],
  "assumptions": [
    "A compatible Hyperledger Fabric release or module revision exists, or can be selected, containing the reusable implementations required by the SDK.",
    "The work is limited to the Go SDK repository and its dependency/module configuration; changes to Fabric peer, orderer, CA, or chaincode runtime behavior are out of scope.",
    "Existing SDK tests and test fixtures are available and can be used as the behavioral baseline.",
    "No intentional backward-incompatible public SDK API redesign is required.",
    "The estimate includes investigation, implementation, local refactoring, tests, documentation, and CI/build updates, but excludes elapsed waiting time for external reviews or upstream merges.",
    "The estimate is for one developer performing the work, with no parallelization benefit.",
    "The exact set of copied files may differ from the linked paths; the estimate covers the complete relevant dependency areas represented by the user stories.",
    "Security audits, performance benchmarking, and extensive cross-version support beyond the selected Fabric dependency version are not required.",
    "All estimates are work-hours and represent single most likely values rather than optimistic or pessimistic ranges."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Repository and dependency inventory",
      "activity_description": "Inspect the copied and modified Fabric packages, identify SDK consumers, map current import paths and APIs, locate affected tests and build targets, and establish the migration baseline.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A2",
      "activity_name": "Dependency and compatibility design",
      "activity_description": "Select compatible Fabric module revisions, define module and import-path strategy, identify required adapters or compatibility shims, and document package ownership and removal boundaries.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A3",
      "activity_name": "Externalize gossip protoext and discovery utilities",
      "activity_description": "Replace the SDK's modified gossip/discovery copy with the selected external implementation, adapt SDK callers as needed, remove obsolete local code, and add focused regression coverage.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A4",
      "activity_name": "Externalize cauthdsl utilities",
      "activity_description": "Migrate SDK consumers from the copied cauthdsl package to the external common package, resolve API or type differences, remove the copied implementation, and verify policy-expression behavior.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A5",
      "activity_name": "Externalize ccprovider structures",
      "activity_description": "Adopt the external ccprovider package, update SDK imports and type references, handle compatibility differences, delete redundant copied files, and run related package tests.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A6",
      "activity_name": "Externalize ledger utilities and structures",
      "activity_description": "Migrate ledger-related SDK usage to the external Fabric ledger packages, resolve transitive dependencies and interfaces, remove local copies, and preserve existing ledger-related behavior through tests.",
      "most_likely_effort": 48
    },
    {
      "activity_id": "A7",
      "activity_name": "Externalize common and core utilities",
      "activity_description": "Replace the broad internally copied common and core Fabric utilities with external module packages, update dependent SDK code, remove modified duplicates, and address resulting package-level incompatibilities.",
      "most_likely_effort": 56
    },
    {
      "activity_id": "A8",
      "activity_name": "Externalize configtxgen functionality",
      "activity_description": "Replace copied configtxgen functions and related resource/configuration code with externalized Fabric functionality, introduce only necessary SDK adapters, and validate configuration generation behavior.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A9",
      "activity_name": "Externalize configtxlator functionality",
      "activity_description": "Migrate configtxlator callers to the external implementation, update serialization and conversion integration points, remove the local copy, and add regression tests for translation workflows.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A10",
      "activity_name": "Implement temporary chaincode go.mod handling",
      "activity_description": "Modify chaincode package processing to honor a go.mod file present in the package during the module transition, constrain the behavior to the intended temporary path, and add focused tests for presence, absence, and malformed files.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A11",
      "activity_name": "SDK-wide import and duplicate-code cleanup",
      "activity_description": "Update all remaining references, remove obsolete internal and third-party copies, resolve dependency graph and package naming issues, run formatting and static checks, and ensure no unintended local fork remains.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A12",
      "activity_name": "Regression, integration, and compatibility testing",
      "activity_description": "Run and repair the full relevant test suite, add cross-package integration coverage, test clean module builds and representative SDK workflows, and diagnose failures caused by dependency or API migration.",
      "most_likely_effort": 48
    },
    {
      "activity_id": "A13",
      "activity_name": "Build, CI, documentation, and release preparation",
      "activity_description": "Update go.mod/go.sum and CI scripts, verify reproducible builds, document dependency and temporary go.mod behavior, update migration notes, and perform final self-review and packaging checks.",
      "most_likely_effort": 16
    }
  ],
  "reported_total": {
    "most_likely_effort": 436
  }
}

